pub(super) fn dispatch(
    engine: &Lodestar,
    name: &str,
    args: &Value,
) -> Option<Result<Value, String>> {
    match name {
        "check_conformance" => Some((|| {
            let evidence = parse_evidence(args)?;
            let result = engine
                .check_conformance(&evidence, opt_str(args, "task_id").as_deref())
                .map_err(|e| e.to_string())?;
            ok(&delivered_check(&result))
        })()),
        "advise" => Some((|| {
            let node_ids = str_array(args, "node_ids");
            let workflow = str_array(args, "workflow");
            let advice = engine
                .advise(opt_str(args, "task_id").as_deref(), &node_ids, &workflow)
                .map_err(|e| e.to_string())?;
            rendered(render_advice(&advice), &advice)
        })()),
        "conformance_history" => Some((|| {
            ok(&engine
                .conformance_history(req_str(args, "task_id")?)
                .map_err(|e| e.to_string())?)
        })()),
        "certification_status" => Some((|| {
            let status = engine
                .certification_status(
                    req_str(args, "task_id")?,
                    opt_str(args, "at_commit").as_deref(),
                )
                .map_err(|e| e.to_string())?;
            rendered(render_status(&status), &status)
        })()),
        _ => None,
    }
}

fn delivered_check(check: &ConformanceCheck) -> DeliveredConformanceCheck<'_> {
    DeliveredConformanceCheck {
        id: check.id,
        token: &check.token,
        conformance: delivered_findings(check.verdict, &check.findings),
    }
}

pub(super) fn delivered_completion_conformance(
    result: &ConformanceResult,
) -> DeliveredCompletionConformance {
    let (findings, findings_truncated) = findings_preview(&result.findings);
    DeliveredCompletionConformance {
        verdict: result.verdict,
        finding_count: result.findings.len(),
        findings,
        findings_truncated,
    }
}

fn delivered_findings(verdict: Verdict, findings: &[String]) -> DeliveredConformance {
    let (findings_preview, findings_truncated) = findings_preview(findings);
    DeliveredConformance {
        verdict,
        finding_count: findings.len(),
        findings_preview,
        findings_truncated,
    }
}

fn findings_preview(findings: &[String]) -> (Vec<String>, bool) {
    let mut preview = Vec::new();
    let mut used_bytes = 0;
    let mut truncated = false;

    for finding in findings {
        if preview.len() == FINDINGS_PREVIEW_ITEMS || used_bytes == FINDINGS_PREVIEW_BYTES {
            truncated = true;
            break;
        }
        let remaining = FINDINGS_PREVIEW_BYTES - used_bytes;
        let mut end = finding.len().min(remaining);
        while !finding.is_char_boundary(end) {
            end -= 1;
        }
        if end == 0 && !finding.is_empty() {
            truncated = true;
            break;
        }
        preview.push(finding[..end].to_string());
        used_bytes += end;
        if end < finding.len() {
            truncated = true;
            break;
        }
    }

    (
        preview,
        truncated || findings.len() > FINDINGS_PREVIEW_ITEMS,
    )
}

pub(super) fn parse_evidence(args: &Value) -> Result<ConformanceEvidence, String> {
    let evidence = args
        .get("evidence")
        .cloned()
        .ok_or_else(|| "missing required object arg: evidence".to_string())?;
    serde_json::from_value(evidence).map_err(|error| format!("invalid evidence: {error}"))
}

/// Render `advise` output as chat Markdown: the headline disposition, the
/// human-readable findings, and a table of every clause governing the declared
/// scope. The structured `Advice` rides alongside in `structuredContent`.
fn render_advice(advice: &Advice) -> String {
    let mut markdown = format!(
        "**Advice: {}** - {} governing clause(s)\n",
        advice.disposition.as_str(),
        advice.governing.len()
    );
    for finding in &advice.findings {
        markdown.push_str(&format!("\n- {finding}"));
    }
    if !advice.governing.is_empty() {
        markdown.push_str("\n\n| Clause | Kind | Mode | Node |\n|---|---|---|---|\n");
        for clause in &advice.governing {
            markdown.push_str(&format!(
                "| {} | {} | {} | {} |\n",
                clause.goal.title,
                clause.goal.kind.as_str(),
                clause.mode.as_str(),
                clause.node_id
            ));
        }
    }
    markdown
}

/// Render a certification status as the qualified status line of ADR-0090 §2.
///
/// The qualifiers are rendered with the state rather than beneath it, because
/// the honesty has to survive the line being screenshotted: a reader cannot crop
/// "certified against constitution:v3" into "compliant".
fn render_status(status: &CertificationStatus) -> String {
    let mut markdown = format!("**Status: {}**\n\n```text\n", status.state.as_str());
    let unknown = "-".to_string();
    for (label, value) in [
        ("Subject", Some(status.subject.clone())),
        ("Commit", status.commit.clone()),
        (
            "Checked (unix)",
            status.certified_at.map(|at| at.to_string()),
        ),
        (
            "Evidence Bundle",
            status.evidence_bundle.map(|id| id.to_string()),
        ),
        ("Policy Version", status.policy_version.clone()),
    ] {
        markdown.push_str(&format!(
            "{label:<16}{}\n",
            value.as_ref().unwrap_or(&unknown)
        ));
    }
    markdown.push_str("```\n\n");
    markdown.push_str(&format!("- {}\n", status.reason));
    markdown.push_str(&format!(
        "- Coverage: {} clause(s) evaluated, {} not evaluated, over {} changed node(s)\n",
        status.coverage.evaluated.len(),
        status.coverage.not_evaluated.len(),
        status.covered_nodes
    ));
    if let Some(waiver) = &status.waiver {
        markdown.push_str(&format!(
            "- Waiver {} expires at {} (unix); remediation: {}\n",
            waiver.id,
            waiver.expires_at,
            waiver.remediation_task_id.as_deref().unwrap_or("none")
        ));
    }
    markdown
}

#[cfg(test)]
mod tests {
    use super::super::call;
    use super::*;
    use lodestar_core::{ArtifactBindingMode, GoalKind};

    #[test]
    fn malformed_evidence_is_rejected_at_the_tool_boundary() {
        let engine = Lodestar::open_in_memory().unwrap();
        let params = json!({
            "name": "check_conformance",
            "arguments": { "evidence": { "schema_version": 1 } }
        });
        assert!(call(&engine, &params)
            .unwrap_err()
            .contains("invalid evidence"));
    }

    #[test]
    fn oversized_findings_stay_durable_while_the_tool_result_stays_bounded() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(
                GoalKind::Objective,
                "Bound checks",
                "keep the audit usable",
                None,
            )
            .unwrap();
        let node = "artifact:src/bounded.rs";
        engine
            .link_goal_to_artifact(&goal.id, &[node.to_string()], ArtifactBindingMode::Governed)
            .unwrap();
        let task = engine
            .create_task(&goal.id, "bound the result", "keep full findings durable")
            .unwrap();
        engine.claim_task(&task.id, "agent-a", 300).unwrap();

        for index in 0..24 {
            engine
                .record_knowledge(
                    &format!("lesson {index}: {}", "x".repeat(1_024)),
                    &json!({ "nodes": [node] }).to_string(),
                    None,
                )
                .unwrap();
        }

        let claimed = engine.store().get_task(&task.id).unwrap().unwrap();
        let evidence = json!({
            "schema_version": 1,
            "task_id": task.id,
            "agent_id": "agent-a",
            "started_at": claimed.claim_started_at.unwrap(),
            "ended_at": lodestar_core::now_unix(),
            "changed_node_ids": [node],
            "failed_node_ids": [],
            "execution_ids": ["execution:proof"],
            "successful_execution_ids": ["execution:proof"],
            "commit_ids": [],
            "summary": "bounded delivery",
            "provenance": [
                {
                    "source_id": "agent:agent-a",
                    "target_id": "execution:proof",
                    "relation": "observed"
                },
                {
                    "source_id": "execution:proof",
                    "target_id": node,
                    "relation": "modified"
                }
            ]
        });
        let result = call(
            &engine,
            &json!({
                "name": "check_conformance",
                "arguments": { "task_id": task.id, "evidence": evidence.clone() }
            }),
        )
        .unwrap();
        let text = result["content"][0]["text"].as_str().unwrap();
        let delivered: Value = serde_json::from_str(text).unwrap();

        assert!(
            text.len() < 4_096,
            "the transport result must stay below the client spill threshold: {} bytes",
            text.len()
        );
        assert!(delivered.get("findings").is_none());
        assert!(delivered["finding_count"].as_u64().unwrap() >= 24);
        assert_eq!(delivered["findings_truncated"], true);
        let preview_bytes: usize = delivered["findings_preview"]
            .as_array()
            .unwrap()
            .iter()
            .map(|finding| finding.as_str().unwrap().len())
            .sum();
        assert!(preview_bytes <= 2_048);

        let history = engine.conformance_history(&task.id).unwrap();
        assert_eq!(history.len(), 1);
        assert!(history[0].findings.len() > 20_000);
        assert!(history[0].findings.contains("lesson 23"));

        let completion = call(
            &engine,
            &json!({
                "name": "task_transition",
                "arguments": {
                    "task_id": task.id,
                    "to": "complete",
                    "agent": "agent-a",
                    "evidence": evidence,
                    "check": delivered
                }
            }),
        )
        .unwrap();
        let completion_text = completion["content"][0]["text"].as_str().unwrap();
        let completion_body: Value = serde_json::from_str(completion_text).unwrap();
        assert!(completion_text.len() < 4_096);
        let completion_findings = completion_body["conformance"]["findings"]
            .as_array()
            .unwrap();
        assert!(
            completion_findings
                .iter()
                .map(|finding| finding.as_str().unwrap().len())
                .sum::<usize>()
                <= FINDINGS_PREVIEW_BYTES
        );
        assert!(
            completion_body["conformance"]["finding_count"]
                .as_u64()
                .unwrap()
                >= 24
        );
        assert_eq!(completion_body["conformance"]["findings_truncated"], true);
    }

    #[test]
    fn conformance_history_dispatch_returns_the_audit_chain() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "History", "prove it", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "work", "done").unwrap();

        // No checks yet -> empty chain.
        let empty = call(
            &engine,
            &json!({ "name": "conformance_history", "arguments": { "task_id": task.id } }),
        )
        .unwrap();
        let records: Value =
            serde_json::from_str(empty["content"][0]["text"].as_str().unwrap()).unwrap();
        assert!(records.as_array().unwrap().is_empty());
    }

    /// ADR-0090 §2. The status line has to carry its qualifiers, because the
    /// line is what gets shown to the person being sold to. A rendering that
    /// dropped the policy version would be the bare badge the decision refuses.
    #[test]
    fn certification_status_renders_a_qualified_status_line() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let task = engine.create_task(&goal.id, "work", "unproven").unwrap();

        let result = call(
            &engine,
            &json!({ "name": "certification_status", "arguments": { "task_id": task.id } }),
        )
        .unwrap();

        let markdown = result["content"][0]["text"].as_str().unwrap();
        assert!(
            markdown.starts_with("**Status: uncertifiable**"),
            "the state leads, and it is not 'certified': {markdown}"
        );
        assert!(
            markdown.contains("Policy Version"),
            "the qualifier a bare badge would omit: {markdown}"
        );
        assert_eq!(result["structuredContent"]["state"], "uncertifiable");
        assert_eq!(result["structuredContent"]["subject"], task.id);
    }

    #[test]
    fn advise_tool_reports_disposition_and_clauses_over_the_boundary() {
        use lodestar_core::ArtifactBindingMode;
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(
                GoalKind::Constraint,
                "Payments boundary",
                "Payment code stays isolated.",
                None,
            )
            .unwrap();
        let node = "artifact:crates/pay/src/lib.rs".to_string();
        engine
            .link_goal_to_artifact(
                &goal.id,
                std::slice::from_ref(&node),
                ArtifactBindingMode::Governed,
            )
            .unwrap();

        // A governed node with no covering task would drift -> review, and the
        // governing clause is surfaced both in Markdown and structuredContent.
        let governed = call(
            &engine,
            &json!({ "name": "advise", "arguments": { "node_ids": [node] } }),
        )
        .unwrap();
        assert_eq!(governed["structuredContent"]["disposition"], "review");
        assert_eq!(
            governed["structuredContent"]["governing"][0]["goal"]["id"],
            goal.id
        );
        assert!(governed["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("Advice: review"));

        // An unbound node under an existing constitution is clear to proceed.
        let unbound = call(
            &engine,
            &json!({ "name": "advise", "arguments": { "node_ids": ["artifact:src/unrelated.rs"] } }),
        )
        .unwrap();
        assert_eq!(unbound["structuredContent"]["disposition"], "advise");
        assert!(unbound["structuredContent"]["governing"]
            .as_array()
            .unwrap()
            .is_empty());
    }
}
